// === Tab: mySketch ===
function Dot(x_, y_, z_, r_)
{
  this.pos = new p5.Vector(x_, y_, z_);
  this.vel = new p5.Vector();
  this.acc = new p5.Vector();
  this.r = r_;
  this.apply = function(x)
  {
    this.acc.add(x);
  }
  this.update = function()
  {
    this.vel.add(this.acc);
    this.pos.add(this.vel);
    this.acc.mult(0);
    translate(this.pos.x, this.pos.y, this.pos.z);
    ellipse(0, 0, this.r, this.r);
    translate(-this.pos.x, -this.pos.y, -this.pos.z);
  }
}

function Splash(x_, y_, z_, r_)
{
  this.x = x_;
  this.y = y_;
  this.z = z_;
  this.r = 0;
  this.limit = r_;
  this.speed = 3;
  this.update = function()
  {
    if (this.limit <= 0) return true;
    this.r += this.speed;
    this.limit -= this.speed;
    noStroke();
    fill(map(this.x, 0, width, 0, 360), 360, 360)
    translate(this.x, this.y, this.z);
    rotateX(HALF_PI);
    ellipse(0, 0, this.r, this.r);
    rotateX(-HALF_PI);
    translate(-this.x, -this.y, -this.z);
    return false;
  }
}
let dots = [];
let splashes = [];
let ground;

function setup()
{
  createCanvas(1000, 580, WEBGL);
  colorMode(HSB);
  ground = height * 7/8;
  for (let i = 0; i < 100; i++) dots[i] = new Dot(random(width), random(ground), random(-width / 1), 5);
}

function draw()
{
  background(0);
  translate(-width / 2, -height / 2);
  for (let i = 0; i < dots.length; i++)
  {
    dots[i].apply(new p5.Vector(0, 0.08));
    noStroke();
    fill(map(dots[i].pos.y, 0, height, 0, 360), 360, 360);
    dots[i].update();
    if (dots[i].pos.y > ground)
    {
      splashes.push(new Splash(dots[i].pos.x, dots[i].pos.y, dots[i].pos.z, dots[i].r * 10));
      dots[i] = new Dot(random(width), 0, random(-width / 2), 5);
    }
  }
  for (let i = 0; i < splashes.length; i++)
    if (splashes[i].update()) splashes.splice(i, 1);
}

